import React from 'react';
import { Box, Container, Button } from '@mui/material';
import Slider from 'react-slick';
import "slick-carousel/slick/slick.css";
import "slick-carousel/slick/slick-theme.css";

const slides = [
  {
    id: 1,
    image: "https://cdn.gcp.techcareer.net/318x367_2_6e822a550b/318x367_2_6e822a550b.png",
    alt: "TechReport 2023",
    link: "https://go.techcareer.net/0ftU0g"
  },
  {
    id: 2,
    image: "https://cdn.gcp.techcareer.net/luxoft_hackathon_318x367_ac5dacfbee/luxoft_hackathon_318x367_ac5dacfbee.png",
    alt: "Luxoft Hackathon",
    link: "https://www.techcareer.net/hackathon/luxoft-parking-hackathon"
  },
  // ... diğer slide'lar
];

const EventsSlider = () => {
  const settings = {
    dots: true,
    infinite: true,
    speed: 500,
    slidesToShow: 3,
    slidesToScroll: 1,
    autoplay: true,
    autoplaySpeed: 3000,
    responsive: [
      {
        breakpoint: 1024,
        settings: {
          slidesToShow: 2,
        }
      },
      {
        breakpoint: 600,
        settings: {
          slidesToShow: 1,
        }
      }
    ]
  };

  return (
    <Box sx={{ 
      width: '100%',
      position: 'relative',
      backgroundColor: '#f5f5f5'
    }}>
      <Container maxWidth="lg" sx={{ py: 5 }}>
        <Slider {...settings}>
          {slides.map((slide) => (
            <Box
              key={slide.id}
              sx={{
                width: '100%',
                display: 'inline-block'
              }}
            >
              <Box sx={{
                p: 2,
                display: 'flex',
                justifyContent: 'center'
              }}>
                <Box sx={{
                  display: 'flex',
                  justifyContent: 'center',
                  alignItems: 'center'
                }}>
                  <Button
                    href={slide.link}
                    disableElevation
                    sx={{
                      p: 0,
                      '&:hover': {
                        backgroundColor: 'transparent'
                      }
                    }}
                  >
                    <img
                      src={slide.image}
                      alt={slide.alt}
                      style={{
                        width: 250,
                        height: 289,
                        objectFit: 'contain'
                      }}
                      draggable={false}
                    />
                  </Button>
                </Box>
              </Box>
            </Box>
          ))}
        </Slider>
      </Container>
      <Box sx={{
        position: 'absolute',
        bottom: 0,
        left: 0,
        right: 0,
        height: '20px',
        backgroundColor: '#e0e0e0'
      }} />
    </Box>
  );
};

export default EventsSlider;
